/**
 * Monsters & Spells data: a registry of datasets, kept separate from the page.
 *
 * Every dataset declares where it comes from, so the page can show it next to each entry:
 *   meta: { id, kind: 'monster' | 'spell', origin: 'official-srd' | 'fod-original' | 'homebrew',
 *           name, edition, license, licenseUrl?, attribution }
 * Built in:
 *   - SRD 5.2.1 monsters: Assets/Data/srd-5.2.1-monsters.json (generated by tools/build-compendium.mjs)
 *   - SRD 5.2.1 spells: the character engine's spell data (FogRules.spells), so spells exist once in the project
 * Later datasets (licensed packs, the user's homebrew) call FogCompendium.register(dataset) — the page doesn't change.
 *
 * FogCompendium.ready()            → Promise (loads the built-in datasets)
 * FogCompendium.monsters() / spells() → entries, each with `dataset` (its meta) and `complete`
 * FogCompendium.datasets()         → metas
 * FogCompendium.register(ds)       → { ok } or { ok:false, errors }
 * FogCompendium.unregister(id)     → removes a dataset (used to refresh the user's homebrew)
 */
(function (global) {
  'use strict';

  var script = typeof document !== 'undefined' && document.currentScript;
  var DATA_BASE = script && script.src ? new URL('../../../Assets/Data/', script.src).href : 'Assets/Data/';
  var ORIGINS = ['official-srd', 'fod-original', 'homebrew'];
  var SPELL_FIELDS = ['name', 'level', 'school', 'castingTime', 'range', 'components', 'duration', 'description', 'classes'];
  var MONSTER_FIELDS = ['name', 'size', 'type', 'ac', 'hp', 'speed', 'cr', 'abilities'];

  var sets = [];
  var loadErrors = [];
  var loading = null;

  function validateMeta(meta, kind) {
    var e = [];
    if (!meta || typeof meta !== 'object') return ['Missing dataset meta.'];
    if (!meta.id) e.push('meta.id is required.');
    if (meta.kind !== kind) e.push('meta.kind must be "' + kind + '".');
    if (ORIGINS.indexOf(meta.origin) < 0) e.push('meta.origin must be one of ' + ORIGINS.join(', ') + '.');
    if (meta.origin !== 'homebrew' && !meta.license) e.push('meta.license is required for non-homebrew content.');
    if (meta.origin !== 'homebrew' && !meta.attribution) e.push('meta.attribution is required for non-homebrew content.');
    if (!meta.edition) e.push('meta.edition is required (do not mix rules editions).');
    return e;
  }

  function isComplete(entry, fields) {
    return fields.every(function (k) {
      var v = entry[k];
      return v != null && v !== '' && !(Array.isArray(v) && !v.length) && !(typeof v === 'object' && !Array.isArray(v) && !Object.keys(v).length);
    });
  }

  function register(ds) {
    var kind = ds && ds.meta && ds.meta.kind;
    var errors = validateMeta(ds && ds.meta, kind === 'spell' ? 'spell' : 'monster');
    if (!Array.isArray(ds && ds.entries)) errors.push('entries must be an array.');
    if (errors.length) return { ok: false, errors: errors };
    if (sets.some(function (s) { return s.meta.id === ds.meta.id; })) return { ok: false, errors: ['A dataset with id "' + ds.meta.id + '" is already registered.'] };
    var fields = kind === 'spell' ? SPELL_FIELDS : MONSTER_FIELDS;
    var meta = Object.freeze(Object.assign({}, ds.meta, { count: ds.entries.length }));
    sets.push({
      meta: meta,
      entries: ds.entries.map(function (e) {
        return Object.assign({}, e, { key: meta.id + ':' + e.id, dataset: meta, complete: e.complete !== false && isComplete(e, fields) });
      }),
    });
    return { ok: true };
  }

  function ready() {
    if (loading) return loading;
    var rules = global.FogRules;
    if (rules && rules.spells && rules.meta) {
      register({
        meta: {
          id: 'srd-5.2.1-spells', kind: 'spell', origin: 'official-srd', name: 'System Reference Document 5.2.1',
          edition: '2024 (SRD 5.2.1)', license: 'CC BY 4.0', licenseUrl: 'https://creativecommons.org/licenses/by/4.0/legalcode',
          attribution: rules.meta.attribution,
        },
        entries: Object.keys(rules.spells).map(function (id) { return rules.spells[id]; }),
      });
    } else {
      loadErrors.push('The SRD spell data did not load.');
    }
    loading = fetch(DATA_BASE + 'srd-5.2.1-monsters.json', { cache: 'no-cache' })
      .then(function (res) {
        if (!res.ok) throw new Error('HTTP ' + res.status);
        return res.json();
      })
      .then(function (data) {
        var meta = Object.assign({}, data.meta, { name: data.meta.source });
        var r = register({ meta: meta, entries: data.monsters || [] });
        if (!r.ok) loadErrors.push('Monster data rejected: ' + r.errors.join(' '));
      })
      .catch(function (e) {
        loadErrors.push('The SRD monster data could not be loaded (' + (e && e.message ? e.message : 'network error') + ').');
      });
    return loading;
  }

  function entriesOf(kind) {
    var out = [];
    sets.forEach(function (s) { if (s.meta.kind === kind) out.push.apply(out, s.entries); });
    return out;
  }

  global.FogCompendium = {
    ready: ready,
    register: register,
    unregister: function (id) { sets = sets.filter(function (s) { return s.meta.id !== id; }); },
    monsters: function () { return entriesOf('monster'); },
    spells: function () { return entriesOf('spell'); },
    datasets: function () { return sets.map(function (s) { return s.meta; }); },
    errors: function () { return loadErrors.slice(); },
    ORIGINS: ORIGINS.slice(),
  };
})(typeof window !== 'undefined' ? window : globalThis);
